class Solution {
    public List<Integer> goodDaysToRobBank(int[] security,int time){
        int n=security.length;
        int[] left=new int[n],right=new int[n];
        for(int i=1;i<n;i++)if(security[i]<=security[i-1])left[i]=left[i-1]+1;
        for(int i=n-2;i>=0;i--)if(security[i]<=security[i+1])right[i]=right[i+1]+1;
        List<Integer> answer=new ArrayList<>();
        for(int i=0;i<n;i++)if(left[i]>=time&&right[i]>=time)answer.add(i);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun goodDaysToRobBank(security:IntArray,time:Int):List<Int>{
        val n=security.size;
        val left=IntArray(n);
        val right=IntArray(n);
        for(i in 1 until n)if(security[i]<=security[i-1])left[i]=left[i-1]+1;
        for(i in n-2 downTo 0)if(security[i]<=security[i+1])right[i]=right[i+1]+1;
        return security.indices.filter{
            left[it]>=time&&right[it]>=time
        }
    }
}

